alter table public.technical_service_records add column if not exists service_status text not null default 'in_progress';
alter table public.technical_service_records drop constraint if exists technical_service_records_service_status_check;
alter table public.technical_service_records add constraint technical_service_records_service_status_check check (service_status in ('in_progress','completed','notify_customer'));
alter table private.technical_service_record_history add column if not exists service_status text;
create or replace function private.capture_technical_service_record_history() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into private.technical_service_record_history (record_id,operation,changed_by,service_type,service_code,barcode,first_name,last_name,phone,complaint,fault_description,service_status,damage_cost,labor_cost,amount_paid,created_by,archived_at,archived_by,created_at,updated_at) values (coalesce(new.id,old.id),tg_op,auth.uid(),coalesce(new.service_type,old.service_type),coalesce(new.service_code,old.service_code),coalesce(new.barcode,old.barcode),coalesce(new.first_name,old.first_name),coalesce(new.last_name,old.last_name),coalesce(new.phone,old.phone),coalesce(new.complaint,old.complaint),coalesce(new.fault_description,old.fault_description),coalesce(new.service_status,old.service_status),coalesce(new.damage_cost,old.damage_cost),coalesce(new.labor_cost,old.labor_cost),coalesce(new.amount_paid,old.amount_paid),coalesce(new.created_by,old.created_by),coalesce(new.archived_at,old.archived_at),coalesce(new.archived_by,old.archived_by),coalesce(new.created_at,old.created_at),coalesce(new.updated_at,old.updated_at)); return coalesce(new,old); end; $$;
revoke all on function private.capture_technical_service_record_history() from public, anon, authenticated;
create index if not exists technical_service_records_service_status_idx on public.technical_service_records(service_status);
